_sage_const_100 = Integer(100); _sage_const_2 = Integer(2); _sage_const_1 = Integer(1); _sage_const_946 = Integer(946); _sage_const_731 = Integer(731); _sage_const_153 = Integer(153); _sage_const_3 = Integer(3); _sage_const_104060 = Integer(104060); _sage_const_6 = Integer(6); _sage_const_127710 = Integer(127710); _sage_const_5 = Integer(5); _sage_const_12788 = Integer(12788); _sage_const_4 = Integer(4); _sage_const_34525 = Integer(34525); _sage_const_8482 = Integer(8482); _sage_const_3298 = Integer(3298); _sage_const_1071 = Integer(1071); _sage_const_3784 = Integer(3784); _sage_const_1032 = Integer(1032); _sage_const_1925 = Integer(1925); _sage_const_853 = Integer(853); _sage_const_328 = Integer(328); _sage_const_184 = Integer(184); _sage_const_1161 = Integer(1161); _sage_const_368 = Integer(368); _sage_const_7 = Integer(7); _sage_const_163 = Integer(163); _sage_const_0 = Integer(0); _sage_const_23 = Integer(23); _sage_const_2145 = Integer(2145); _sage_const_8 = Integer(8); _sage_const_17 = Integer(17); _sage_const_3135 = Integer(3135); _sage_const_16 = Integer(16); _sage_const_30 = Integer(30); _sage_const_440 = Integer(440); _sage_const_660 = Integer(660); _sage_const_160 = Integer(160); _sage_const_43 = Integer(43); _sage_const_64 = Integer(64); _sage_const_20 = Integer(20); _sage_const_19 = Integer(19); _sage_const_1024 = Integer(1024); _sage_const_9 = Integer(9); _sage_const_6407 = Integer(6407); _sage_const_10860 = Integer(10860); _sage_const_128 = Integer(128); _sage_const_1745370 = Integer(1745370); _sage_const_12145238 = Integer(12145238); _sage_const_44886481 = Integer(44886481); _sage_const_92943995 = Integer(92943995); _sage_const_102256019 = Integer(102256019); _sage_const_46709052 = Integer(46709052); _sage_const_57792 = Integer(57792); _sage_const_351019 = Integer(351019); _sage_const_1059230 = Integer(1059230); _sage_const_1587211 = Integer(1587211); _sage_const_944620 = Integer(944620); _sage_const_4515 = Integer(4515); _sage_const_5399 = Integer(5399); _sage_const_60 = Integer(60)
from ore_algebra import *
from ore_algebra import guess

R = PolynomialRing(QQ, names=('n',)); (n,) = R._first_ngens(1)
A = OreAlgebra(R, names=('Sn',)); (Sn,) = A._first_ngens(1)

N = _sage_const_100

# AESZ inner sum
inner = []
for nn in range(N):
    inner.append(sum(binomial(nn,k)**_sage_const_2  * binomial(nn+k,nn) * binomial(nn+_sage_const_2 *k,nn) for k in range(nn+_sage_const_1 )))

# Zudilin b2 and b3 companions
# Use Zudilin recurrence to compute them
def z3(nn): return ZZ(_sage_const_2 *(_sage_const_946 *nn**_sage_const_2 -_sage_const_731 *nn+_sage_const_153 )*(_sage_const_2 *nn+_sage_const_1 )*(nn+_sage_const_1 )**_sage_const_3 )
def z2_c(nn): return ZZ(-_sage_const_2 *(_sage_const_104060 *nn**_sage_const_6 +_sage_const_127710 *nn**_sage_const_5 +_sage_const_12788 *nn**_sage_const_4 -_sage_const_34525 *nn**_sage_const_3 -_sage_const_8482 *nn**_sage_const_2 +_sage_const_3298 *nn+_sage_const_1071 ))
def z1(nn): return ZZ(_sage_const_2 *nn*(_sage_const_3784 *nn**_sage_const_5 -_sage_const_1032 *nn**_sage_const_4 -_sage_const_1925 *nn**_sage_const_3 +_sage_const_853 *nn**_sage_const_2 +_sage_const_328 *nn-_sage_const_184 ))
def z0(nn): return ZZ(-(_sage_const_946 *nn**_sage_const_2 +_sage_const_1161 *nn+_sage_const_368 )*nn*(nn-_sage_const_1 )**_sage_const_3 )

def zudilin_rec(init):
    u = list(init)
    for nn in range(_sage_const_2 , N):
        u.append((-z2_c(nn)*u[nn] - z1(nn)*u[nn-_sage_const_1 ] - z0(nn)*u[nn-_sage_const_2 ]) / z3(nn))
    return u

a = zudilin_rec([QQ(_sage_const_1 ), QQ(_sage_const_7 ), QQ(_sage_const_163 )])
b2 = zudilin_rec([QQ(_sage_const_0 ), QQ(_sage_const_23 )/_sage_const_2 , QQ(_sage_const_2145 )/_sage_const_8 ])
b3 = zudilin_rec([QQ(_sage_const_0 ), QQ(_sage_const_17 )/_sage_const_2 , QQ(_sage_const_3135 )/_sage_const_16 ])

# Verify a matches inner sum
for nn in range(min(N, _sage_const_30 )):
    assert a[nn] == inner[nn], f"Mismatch at n={nn}"
print("Zudilin a matches inner sum. ✓")

# c_j(1) for the Cauchy twist
c = [QQ(_sage_const_1 )]
for nn in range(N+_sage_const_5 ):
    cm1 = c[nn-_sage_const_1 ] if nn >= _sage_const_1  else QQ(_sage_const_0 )
    cm2 = c[nn-_sage_const_2 ] if nn >= _sage_const_2  else QQ(_sage_const_0 )
    c.append(((_sage_const_440 *nn+_sage_const_660 )*c[nn] + (_sage_const_160 -_sage_const_16 *nn)*cm1 + (_sage_const_2 *nn-_sage_const_43 )*cm2) / (_sage_const_8 *(nn+_sage_const_1 )))

print(f"c[0:5] = {c[:_sage_const_5 ]}")
print(f"c[5] = {c[_sage_const_5 ]}")

# Cauchy twist: (C₁ f)_n = (1/64^n) Σ_{m=0}^n c_{n-m} f_m
def cauchy_twist(seq):
    return [sum(c[nn-m]*seq[m] for m in range(nn+_sage_const_1 )) / QQ(_sage_const_64 )**nn
            for nn in range(N)]

ta = cauchy_twist(a)
tb2 = cauchy_twist(b2)
tb3 = cauchy_twist(b3)

print(f"\nTwisted a: ta[0:5] = {[float(x) for x in ta[:_sage_const_5 ]]}")
print(f"Growth ta[20]/ta[19] = {float(ta[_sage_const_20 ]/ta[_sage_const_19 ]):.10f}")

# Guess the recurrence for the twisted sequence ta
print(f"\nGuessing recurrence for Cauchy-twisted a_n...")
L_twist = guess(ta, A)
print(f"L_twist: order={L_twist.order()}, degree={max(c.degree() for c in L_twist.list())}")

# P2.7 operator
A_fn = R(_sage_const_1024 *(_sage_const_2 *n+_sage_const_5 )**_sage_const_4 *(_sage_const_2 *n+_sage_const_7 )**_sage_const_3 *(_sage_const_2 *n+_sage_const_9 )**_sage_const_3 *(_sage_const_946 *n**_sage_const_2 +_sage_const_6407 *n+_sage_const_10860 ))
B_fn = R(_sage_const_128 *(_sage_const_2 *n+_sage_const_7 )**_sage_const_3 *(_sage_const_2 *n+_sage_const_9 )**_sage_const_3 *(_sage_const_104060 *n**_sage_const_6 +_sage_const_1745370 *n**_sage_const_5 +_sage_const_12145238 *n**_sage_const_4 +_sage_const_44886481 *n**_sage_const_3 +_sage_const_92943995 *n**_sage_const_2 +_sage_const_102256019 *n+_sage_const_46709052 ))
C_fn = R(_sage_const_16 *(n+_sage_const_3 )**_sage_const_4 *(_sage_const_2 *n+_sage_const_9 )**_sage_const_3 *(_sage_const_3784 *n**_sage_const_5 +_sage_const_57792 *n**_sage_const_4 +_sage_const_351019 *n**_sage_const_3 +_sage_const_1059230 *n**_sage_const_2 +_sage_const_1587211 *n+_sage_const_944620 ))
D_fn = R((n+_sage_const_3 )**_sage_const_4 *(n+_sage_const_4 )**_sage_const_6 *(_sage_const_946 *n**_sage_const_2 +_sage_const_4515 *n+_sage_const_5399 ))

A0, A1, A2 = A_fn(n=n), A_fn(n=n+_sage_const_1 ), A_fn(n=n+_sage_const_2 )
B2 = B_fn(n=n+_sage_const_2 )
C1 = C_fn(n=n+_sage_const_1 )
D0 = D_fn(n=n)

c3_p = A0 * A1 * A2
c2_p = -A0 * A1 * B2
c1_p = A0 * A2 * C1
c0_p = -A1 * A2 * D0
g = gcd([c3_p, c2_p, c1_p, c0_p])
